-  void toStringBuilder(StringBuilder b) {
-    switch (kind) {
-      case REGEXP_UNION:
-        b.append("(");
-        exp1.toStringBuilder(b);
-        b.append("|");
-        exp2.toStringBuilder(b);
-        b.append(")");
-        break;
-      case REGEXP_CONCATENATION:
-        exp1.toStringBuilder(b);
-        exp2.toStringBuilder(b);
-        break;
-      case REGEXP_INTERSECTION:
-        b.append("(");
-        exp1.toStringBuilder(b);
-        b.append("&");
-        exp2.toStringBuilder(b);
-        b.append(")");
-        break;
-      case REGEXP_OPTIONAL:
-        b.append("(");
-        exp1.toStringBuilder(b);
-        b.append(")?");
-        break;
-      case REGEXP_REPEAT:
-        b.append("(");
-        exp1.toStringBuilder(b);
-        b.append(")*");
-        break;
-      case REGEXP_REPEAT_MIN:
-        b.append("(");
-        exp1.toStringBuilder(b);
-        b.append("){").append(min).append(",}");
-        break;
-      case REGEXP_REPEAT_MINMAX:
-        b.append("(");
-        exp1.toStringBuilder(b);
-        b.append("){").append(min).append(",").append(max).append("}");
-        break;
-      case REGEXP_COMPLEMENT:
-        b.append("~(");
-        exp1.toStringBuilder(b);
-        b.append(")");
-        break;
-      case REGEXP_CHAR:
-        b.append("\\").appendCodePoint(c);
-        break;
-      case REGEXP_CHAR_RANGE:
-        b.append("[\\").appendCodePoint(from).append("-\\").appendCodePoint(to).append("]");
-        break;
-      case REGEXP_ANYCHAR:
-        b.append(".");
-        break;
-      case REGEXP_EMPTY:
-        b.append("#");
-        break;
-      case REGEXP_STRING:
-        b.append("\"").append(s).append("\"");
-        break;
-      case REGEXP_ANYSTRING:
-        b.append("@");
-        break;
-      case REGEXP_AUTOMATON:
-        b.append("<").append(s).append(">");
-        break;
-      case REGEXP_INTERVAL:
-        String s1 = Integer.toString(min);
-        String s2 = Integer.toString(max);
-        b.append("<");
-        if (digits > 0) for (int i = s1.length(); i < digits; i++)
-          b.append('0');
-        b.append(s1).append("-");
-        if (digits > 0) for (int i = s2.length(); i < digits; i++)
-          b.append('0');
-        b.append(s2).append(">");
-        break;
-      case REGEXP_PRE_CLASS:
-        b.append("\\").appendCodePoint(from);
-        break;
-    }
-  }
