-        b.append('\n');
-        break;
-      case REGEXP_ANYSTRING:
-        b.append(indent);
-        b.append(kind);
-        b.append('\n');
-        break;
-      case REGEXP_AUTOMATON:
-        b.append(indent);
-        b.append(kind);
-        b.append('\n');
-        break;
-      case REGEXP_INTERVAL:
-        b.append(indent);
-        b.append(kind);
-        String s1 = Integer.toString(min);
