+        this.repositoryStats = repositoryStats;
+        this.clusterVersion = clusterVersion;
+        this.archived = archived;
+    }
+
+    public RepositoryStatsSnapshot(StreamInput in) throws IOException {
+        this.repositoryInfo = new RepositoryInfo(in);
